import { RIGHT } from '@shell/utils/position';

export const PRODUCT_NAME = 'kopilot-ui';
export const BLANK_CLUSTER = '_';

export const AGENT_NAME = 'kopilot-agent';
export const AGENT_NAMESPACE = 'kopilot-system';
export const TOOLS_CONFIG_NATIVE_NAME = 'kopilot-native-ui-tools'
export const TOOLS_CONFIG_RANCHER_NAME = 'kopilot-rancher-ui-tools'
export const AGENT_CONFIG_LLM_SECRET_NAME = 'kopilot-llm-config';
export const AGENT_CONFIG_SECRET_NAME = 'kopilot-agent-secret';
export const OPERATOR_SECRET_NAME = 'kopilot-operator-secret'
export const AGENT_CONFIG_CONFIG_MAP_NAME = 'kopilot-agent-config';
export const AGENT_WEB_UI_SERVICE_NAME = 'kopilot-webui'
export const PANEL_POSITION = RIGHT;

export const KOPILOT_AI_SCHEMA = {
  AI_AGENT_CONFIG: 'kopilot.pandaria.io.subagentconfig'
}

export function init($plugin, store) {
  // Configure Settings page to include AI Assistant settings
  const { virtualType, basicType } = $plugin.DSL(store, 'settings');

  basicType([PRODUCT_NAME]);

  virtualType({
    labelKey: 'kopilotAIConfig.label',
    name:       PRODUCT_NAME,
    namespaced: false,
    route:      { name: `c-cluster-settings-${ PRODUCT_NAME }` }
  });
}
