<script setup>
import { ModelSettings } from 'kopilot-ui-components';
import { useI18n } from '@shell/composables/useI18n';
import { AGENT_NAMESPACE,  KOPILOT_AI_SCHEMA, } from '../../product';
import {onMounted, computed, ref, provide} from 'vue'
import { SECRET, CONFIG_MAP } from '@shell/config/types';
import { useStore } from 'vuex';
import Loading from '@shell/components/Loading.vue';
import Banner from '@components/Banner/Banner.vue';
import {useSharedAgents} from '../../composables/useAgents'
import {useSharedTools} from '../../composables/useTools'
import {useSharedModels} from '../../composables/useModels'


const {modelSettings, fetchModelSetings, saveModelSettings } = useSharedModels()
const {aiAgentConfigCRDs, oauth2Secrets, fetchAgentCRDS, saveAgentsSettings} = useSharedAgents()
const {uiToolsNeedCreate, uiToolsSettings, fetchUIToolsConfigSettings, saveToolsSettings, createToolsDefinition } = useSharedTools()
const store = useStore();
const { t } = useI18n(store);
const isLoading = ref(false);
const saveError = ref(null)
const errorMap = ref(new Map())
const errorMessage = computed(() => {
  if (errorMap.value?.size > 0) {
    return [...errorMap.value?.values()].map((v) => v).join(', ')
  }

  return null
})

const permissions = computed(() => {
  const canListConfigMaps = store.getters['management/canList'](CONFIG_MAP);
  const canListSecrets = store.getters['management/canList'](SECRET);
  const canListAiAgentCRDS = canListSecrets && store.getters['management/canList'](KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG);

  let schema = store.getters['management/schemaFor'](KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG);
  const canCreateAiAgentCRDS = !!schema?.resourceMethods?.find((verb) => 'PUT' === verb);

  schema = store.getters['management/schemaFor'](SECRET);
  const canCreateSecrets = !!schema?.resourceMethods?.find((verb) => 'PUT' === verb);
  
  schema = store.getters['management/schemaFor'](CONFIG_MAP);
  const canCreateConfigMaps = !!schema?.resourceMethods?.find((verb) => 'PUT' === verb);

  return {
    list:   {
      canListConfigMaps,
      canListSecrets,
      canListAiAgentCRDS,
    },
    create: {
      canCreateSecrets,
      canCreateConfigMaps,
      canCreateAiAgentCRDS,
    }
  }
})

async function fetchSettings() {
  Promise.all([
    fetchModelSetings(errorMap),
    fetchUIToolsConfigSettings(errorMap),
    fetchAgentCRDS(errorMap)
  ])
}

async function saveSettings(formData, aiAgentsFormData, aiToolsRancherFormData) {
  saveError.value = []
  isLoading.value = true;
  const promises = [saveModelSettings(formData, saveError), saveAgentsSettings(aiAgentsFormData, saveError)]
  if (uiToolsNeedCreate.value === false) {
    promises.push(saveToolsSettings(aiToolsRancherFormData, saveError))
  }
  await Promise.allSettled(promises)
  isLoading.value = false;
}

const hasNoPermission = computed(() => {
  return [...Object.values(permissions.value?.list ?? {})].some((item) => item === false) || [...Object.values(permissions.value?.create ?? {})].some((item) => item === false)
})

const SECRET_TYPES = {
  OPAQUE: 'Opaque',
  SERVICE_ACCT: 'kubernetes.io/service-account-token',
  DOCKER_JSON: 'kubernetes.io/dockerconfigjson',
  BASIC: 'kubernetes.io/basic-auth',
  SSH: 'kubernetes.io/ssh-auth',
  TLS: 'kubernetes.io/tls',
  BOOTSTRAP: 'bootstrap.kubernetes.io/token',
  ISTIO_TLS: 'istio.io/key-and-cert',
  HELM_RELEASE: 'helm.sh/release.v1',
  FLEET_CLUSTER: 'fleet.cattle.io/cluster-registration-values',
  CLOUD_CREDENTIAL: 'provisioning.cattle.io/cloud-credential',
  RKE_AUTH_CONFIG: 'rke.cattle.io/auth-config',
  FLEET_OCI_STORAGE: 'fleet.cattle.io/bundle-oci-storage/v1alpha1',
}
const fetchBasicAuthSecrets = () => {
  const p = new URLSearchParams()
  p.append('pagesize', '100000')
  p.append('filter', `metadata.fields[1]="${SECRET_TYPES.BASIC}"`)
  p.append('exclude', 'metadata.managedFields')
  return store.dispatch(`management/request`, {
    url: `/v1/secrets/${AGENT_NAMESPACE}?${p.toString()}`,
    method: 'GET',
  });
}

const fetchHeaderAuthSecrets = () => {
  const p = new URLSearchParams()
  const filters = [...Object.values(SECRET_TYPES)].filter((v) => v !== SECRET_TYPES.BASIC).map((v) => `metadata.fields[1]="${v}"`).join(',')
  p.append('page', '1')
  p.append('pagesize', '10000')
  p.append('sort', 'metadata.name')
  p.append('filter',  `metadata.namespace=${AGENT_NAMESPACE}`)
  // p.append('filter',  'metadata.fields[1]=Opaque,metadata.fields[1]="kubernetes.io/service-account-token",metadata.fields[1]="kubernetes.io/dockerconfigjson",metadata.fields[1]="kubernetes.io/basic-auth",metadata.fields[1]="kubernetes.io/ssh-auth",metadata.fields[1]="kubernetes.io/tls",metadata.fields[1]="bootstrap.kubernetes.io/token",metadata.fields[1]="istio.io/key-and-cert",metadata.fields[1]="helm.sh/release.v1",metadata.fields[1]="fleet.cattle.io/cluster-registration-values",metadata.fields[1]="provisioning.cattle.io/cloud-credential",metadata.fields[1]="rke.cattle.io/auth-config",metadata.fields[1]="fleet.cattle.io/bundle-oci-storage/v1alpha1"')
  p.append('filter', filters)
  p.append('exclude', 'metadata.managedFields')
  return store.dispatch(`management/request`, {
    url: `/v1/secrets?${p.toString()}`,
    method: 'GET',
  });
}

const fetchSecrets = () => {
  const p = new URLSearchParams()
  const filters = [...Object.values(SECRET_TYPES)].map((v) => `metadata.fields[1]="${v}"`).join(',')
  p.append('page', '1')
  p.append('pagesize', '10000')
  p.append('sort', 'metadata.name')
  p.append('filter',  `metadata.namespace=${AGENT_NAMESPACE}`)
  p.append('filter', filters)
  p.append('exclude', 'metadata.managedFields')
  return store.dispatch(`management/request`, {
    url: `/v1/secrets?${p.toString()}`,
    method: 'GET',
  });
}
const baseUrl = localStorage.getItem('DEV_KOPILOT_BACKEND_URL') ?? '/api/v1/namespaces/kopilot-system/services/http:kopilot-webui:8080/proxy';
provide('settingsContext', {
  baseUrl,
  t,
  fetchSecrets,
  fetchHeaderAuthSecrets,
  fetchBasicAuthSecrets,
  createToolsDefinition,
  toast: {
    show: (option) => {
      store.dispatch(`growl/${ option.type }`, {
        title:   option.title,
        message: option.description
      }, { root: true });
    }
  }
})
onMounted(async () => {
  isLoading.value = true;
  await fetchSettings();
  isLoading.value = false;
});

</script>
<template>
  <loading v-if="isLoading" />
  <template v-else-if="hasNoPermission || errorMessage">
    <Banner
      class="m-0"
      color="warning"
    >
      <div v-html="t('kopilotAIConfig.form.warning.missingPermissions', {}, true)"></div>
    </Banner>
  </template>
  <template v-else>
      <ModelSettings
        class="kopilot-ui"
        :loading="isLoading"
        :settings="modelSettings"
        :agentsSettings="aiAgentConfigCRDs"
        :oauth2Secrets="oauth2Secrets"
        :toolsSettings="uiToolsSettings"
        :settingsReadOnly="!permissions?.create.canCreateSecrets"
        :agentsReadOnly="!permissions?.create.canCreateSecrets || !permissions?.create.canCreateAiAgentCRDS"
        :toolsReadOnly="!permissions?.create.canCreateConfigMaps"
        :toolsNeedCreate="uiToolsNeedCreate"
        :save="saveSettings"
        :error="saveError"/>
  </template>
</template>
