import { useI18n } from '@shell/composables/useI18n';

const HookContextTag = {
  SortableTableRow: '__sortable-table-row',
  DetailsState: '__details-state',
  StatusBanner: '__details-state-banner',
}
const Role = {
  User: 'user',
  Assistant: 'assistant',
  System: 'system',
}

/**
 * Factory for creating template messages based on context.
 *
 * It's used in Hooks overlays to generate user messages for the AI based on the selected resource
 */
class TemplateMessageFactory {
  fill(store, ctx, globalCtx) {
    const { t } = useI18n(store);

    let messageContent = t('kopilot.message.template.heyAnalyzeResource');
    let summaryContent = '';

    const resource = ctx.value;

    // Add resource as context
    const resourceCtx = [{
      tag:         resource?.kind?.toLowerCase(),
      description: resource?.kind,
      icon:        ctx.icon,
      value:       resource?.name
    }];

    // Add resource's namespace as context if available
    const resourceNamespaceCtx = resource?.namespace ? [{
      tag:         'namespace',
      description: t('kopilot.message.template.namespace'),
      icon:        'icon-namespace',
      value:       resource?.namespace
    }] : [];

    const state = resource.state || resource.stateDisplay;

    switch (ctx.tag) {
    case HookContextTag.SortableTableRow:
    case HookContextTag.DetailsState:
      summaryContent = t('kopilot.message.template.summary.analyseKindAndTroubleshoot', {
        kind: resource.kind,
        name: resource.name
      }, true);
      messageContent = t('kopilot.message.template.message.explainStateForResource', {
        state,
        kind:      resource.kind,
        name:      resource.name,
        namespace: resource.namespace || null
      }, true);

      if (state?.toLowerCase() !== 'active' && state?.toLowerCase() !== 'running' && state?.toLowerCase() !== 'ready') {
        messageContent += `\n  - ${ t('kopilot.message.template.bullet.identifyCause') }\n  - ${ t('kopilot.message.template.bullet.provideActions') }`;
      } else {
        messageContent += `\n  - ${ t('kopilot.message.template.bullet.confirmExpectedState') }`;
      }
      break;
    case HookContextTag.StatusBanner:
      const { label, color } = resource.bannerProps || {};

      const issueText = color === 'error' ? t('kopilot.message.template.theError') : t('kopilot.message.template.anyProblems');

      summaryContent = t('kopilot.message.template.summary.analyseBanner', {
        label,
        issue: issueText
      }, true);
      messageContent = t('kopilot.message.template.message.explainStateForResource', {
        state,
        kind:      resource.kind,
        name:      resource.name,
        namespace: resource.namespace || null
      }, true);

      if (state?.toLowerCase() !== 'active' && state?.toLowerCase() !== 'running' && state?.toLowerCase() !== 'ready') {
        messageContent += `\n  - ${ t('kopilot.message.template.bullet.identifyCause') }\n  - ${ t('kopilot.message.template.bullet.provideActions') }`;
      } else {
        messageContent += `\n  - ${ t('kopilot.message.template.bullet.confirmExpectedState') }`;
      }
      break;
    default:
      break;
    }

    const contextContent = [
      ...(globalCtx || []),
      ...resourceCtx,
      ...resourceNamespaceCtx
    ].filter((item, index, self) => index === self.findIndex((c) => c.tag === item.tag && c.value === item.value));

    return {
      role:      Role.User,
      messageContent,
      summaryContent,
      contextContent,
      completed: true
    };
  }
}

export default new TemplateMessageFactory();
