<script setup>
import 'kopilot-ui-components/style.css';
import Loading from '@shell/components/Loading.vue';
import { useStore } from 'vuex';
import { useI18n } from '@shell/composables/useI18n';
import { useHeaderComposable } from '../composables/useHeaderComposable';
import {  ChatView } from 'kopilot-ui-components';
import { NORMAN, MANAGEMENT, METRIC, CATALOG, EVENT, FLEET, NODE, POD, WORKLOAD_TYPES } from '@shell/config/types';
import { ref, provide, onBeforeUnmount, onMounted, computed } from 'vue';
import { base64Decode } from '@shell/utils/crypto';
import { SECRET, CONFIG_MAP, CAPI } from '@shell/config/types';
import { AGENT_NAMESPACE, PRODUCT_NAME } from '../product';
import toolsConfigData from '../assets/rancher_ui_tools.json'
import {useSharedAgents} from '../composables/useAgents'
import {useSharedModels} from '../composables/useModels'
import {useSharedTools} from '../composables/useTools'
import {useAIService} from '../composables/useAIService'
import {getProduct, getDetailLocation, getInStore, isManagementStore, normalizeType,
  getManagementSchema,
  isManagementGroup,
  normalizeId} from '../composables/resource-context'
import { STORE } from '@shell/store/store-types';

defineOptions({name: 'KopilotUI'});
defineProps({
  tab: {
    type: Object,
  },
  active: {
    type: Boolean
  },
  width: {
    type: [String, Number]
  },
  height: {
    type: [String, Number]
  }
});
const store = useStore();
const { t } = useI18n(store);
const {
  resize,
  close: closePanel,
  restore,
} = useHeaderComposable();

const isLoading = ref(false)
const {aiAgentConfigCRDs: allAgents, fetchAgentCRDS} = useSharedAgents()
const {llmSecret: llmConfig, permissions, fetchLLMConfig} = useSharedModels()
const {uiToolsNeedCreate, uiToolsSettings, fetchUIToolsConfigSettings} = useSharedTools()
const {error: errorAgentDeployment, aiAgentDeploymentState} = useAIService()
const errorMap = ref(new Map())
const errorMessage = computed(() => {
  if (errorMap.value?.size > 0) {
    return [...errorMap.value?.values()].map((v) => v.message).join(', ')
  }

  return null
})

const getStateErrorMessage = (agent) => {
  if (agent?.status?.phase?.toLowerCase() === 'failed') {
    return agent?.status?.conditions[0]?.message ?? ''
  }
  return ''
}
const agents = computed(() => {
  return allAgents.value.filter((item) => item.spec.enabled && !getStateErrorMessage(item))
})
const close = () => {
  closePanel();
}
const fetchConfig = async () => {
  isLoading.value = true;
  await Promise.all([fetchAgentCRDS(errorMap), fetchLLMConfig(errorMap), fetchUIToolsConfigSettings(errorMap)])
  isLoading.value = false;
}

const clusterIdToNameMap = computed(() => {
  const clusters =  store.getters['management/all'](MANAGEMENT.CLUSTER);
  return clusters.reduce((t,c) => {
    t.set(c.id, c.spec.displayName)
    return t
  }, new Map())
})
onMounted(() => {
  fetchConfig()
})
onBeforeUnmount(() => {
  restore();
});

function goToSettings() {
  store.state.$router.push({
    name:   `c-cluster-settings-${ PRODUCT_NAME }`,
    params: { cluster: store.state.$route.params.cluster || 'local' },
  });
}

const baseUrl = localStorage.getItem('DEV_KOPILOT_BACKEND_URL') ?? '/api/v1/namespaces/kopilot-system/services/http:kopilot-webui:8080/proxy';
const v3User = store.getters['auth/user'] ?? store.getters['auth/selfUser'] ?? store.getters['auth/v3User'];
const globalEnvContexts = computed(() => store.getters['kopilot-ui/context/all']);

const navigateToRoute = (route) => {
  if (route) {
    store.state.$router.push(route);
  } else {
    console.warn(`Unknown route: ${ route }`);
  }
}
const openConsoleLogs = async (cluster, pod, containerName) => {
  if (!cluster) {
    console.warn('Cannot open console logs: cluster information is missing');
    return;
  }

  const currentPath = store.state.$router.currentRoute.value.path;
  const expectedBasePath = `/c/${ cluster }/explorer`;

  // If not in explorer route, navigate there first
  if (!currentPath.includes(expectedBasePath)) {
    await store.state.$router.push({ path: expectedBasePath });
  }

  const name = containerName || pod?.spec?.containers?.[0]?.name;

  store.dispatch('wm/open', {
    id:        `${ containerName }-logs`,
    label:     pod?.metadata?.name,
    icon:      'file',
    component: 'ContainerLogs',
    attrs:     {
      pod,
      initialContainer: name
    }
  }, { root: true });
}



async function createToolsDefinition() {
  const configMap = await store.dispatch('management/create', {
    type:     CONFIG_MAP,
    metadata: {
      name:        'kopilot-rancher-ui-tools',
      namespace:   AGENT_NAMESPACE,
      labels:      { app: 'kopilot-rancher-ui-tools' },
    },
    data: {
      config: JSON.stringify(toolsConfigData),
    }
  });

  try {
    await configMap.save();
  } catch (err) {
    console.warn(`Unable to create UI Tools Config ConfigMap ${ configMap.metadata.name }: `, { err });

    return {
      action:  'create',
      success: false,
      message: err
    };
  }
  await fetchUIToolsConfigSettings();
  return {
    action:  'create',
    success: true,
  };
}

const llm = computed(() => {
  const config = llmConfig?.value
  return {
    model: base64Decode(config?.data?.['LLM_MODEL'] ?? ''),
    provider: base64Decode(config?.data?.['LLM_PROVIDER'] ?? '')
  }
})
const theme = computed(() => {
  return store.getters['prefs/theme']
})
const TYPES_FOR_EXPLORER = {
  CATALOG, EVENT, FLEET, MANAGEMENT, NODE, POD, WORKLOAD_TYPES
}
const principal = computed(() => {
  return store.getters['rancher/byId'](NORMAN.PRINCIPAL, store.getters['auth/principalId']) || {};
})
const resourceContext = {
  getProduct, getDetailLocation, getInStore, isManagementStore, normalizeType,
  getManagementSchema,
  isManagementGroup,
  normalizeId
};

const context = {
  t,
  store,
  navigateToRoute,
  openConsoleLogs,
  goToSettings,
  resourceContext,
  clusterIdToNameMap,
  permissions,
  llm,
  agents,
  theme,
  globalEnvContexts,
  authUser:  v3User,
  avatarSrc:  store.getters['rancher/byId'](NORMAN.PRINCIPAL, store.getters['auth/principalId'])?.avatarSrc,
  baseUrl,
  close:     closePanel,
  TYPES_FOR_EXPLORER,
  principal,
  uiToolsNeedCreate,
  uiToolsSettings,
  apis:      {
    createToolsDefinition,
    hasSchema: (schema, inStore = 'management') => {
      return store.getters[`${ inStore }/schemaFor`](schema)
    },
    // findResource: (cluster, type, namespace, name, inStore = STORE.MANAGEMENT) => {
    //   if (!cluster || !namespace || !name) {
    //     return null;
    //   }
    //   const id = `${ namespace }/${ name }`;

    //   return store.getters[`${ inStore }/byId`](type, id);
    // },
    fetchAllClusters: (inStore = 'management') => {
      return store.dispatch(`${ inStore }/findAll`, { type: MANAGEMENT.CLUSTER });
    },
    fetchResource: async ({cluster, type, namespace, name, inStore = STORE.MANAGEMENT}) => {
      if (!cluster || !namespace || !name) {
        return null;
      }
      try {
        const id = `${ namespace }/${ name }`;

        if (cluster === 'local') {
          return await store.dispatch(`${ inStore }/find`, {
            cluster,
            type,
            id,
          });
        } else {
          const url = `/k8s/clusters/${ cluster }/v1`;

          const data = await store.dispatch(`${ inStore }/request`, { url: `${ url }/${ type }s/${ id }?exclude=metadata.managedFields` });

          // Convert to model and store in cache
          await store.dispatch(`${ inStore }/load`, {
            data,
            invalidatePageCache: false
          });
          return data
        }
      } catch (e) {
        console.warn(`Action - Could not find resource with { cluster: ${ cluster }, type: ${ type }, name: ${ name }, namespace: ${ namespace } }`, e);
      }
    },
    fetchManagement: () => {
      return store.dispatch('loadManagement');
    },
    createSession: (title, model) => {
      return store.dispatch('management/request', {
        url:     `${ baseUrl }/v1/sessions`,
        method:  'POST',
        headers: { 'KOPILOT_USER': v3User?.id },
        data:    { title, model }
      });
    },
    fetchSession: (sessionId, signal, data = {
      count:     false,
      page_size: 1000,
      page:      0,
    }, params = {}) => {
      return store.dispatch('management/request', {
        url:     `${ baseUrl }/v1/sessions/${ sessionId }?action=response`,
        method:  'POST',
        signal,
        headers: { 'KOPILOT_USER': v3User?.id },
        params,
        data,
      });
    },
    fetchSessions: (params = {
      pagesize: 1000,
      page:     0,
      sort:     '-created_at'
    }, signal) => {
      return store.dispatch('management/request', {
        url:                  `${ baseUrl }/v1/sessions`,
        method:               'GET',
        headers: { 'KOPILOT_USER': v3User?.id },
        signal,
        params
      });
    },
    fetchSessionCount: (signal) => {
      return store.dispatch('management/request', {
        url:     `${ baseUrl }/v1/sessions?action=count`,
        headers: { 'KOPILOT_USER': v3User?.id },
        method:  'POST',
        signal
      });
    },
    fetchSessionHistoryCount: (sessionId, signal) => {
      const data = {
        count: true,
      }
      return store.dispatch('management/request',{
        url: `${ baseUrl }/v1/sessions/${sessionId}?action=response`,
        headers: { 'KOPILOT_USER': v3User?.id },
        method: 'post',
        data,
        signal,
      });
    },
    removeSession: (id) => {
      return store.dispatch('management/request', {
        url:     `${ baseUrl }/v1/sessions/${ id }`,
        headers: { 'KOPILOT_USER': v3User?.id },
        method:  'DELETE',
      });
    },
  },
  toast: {
    show: (option) => {
      store.dispatch(`growl/${ option.type }`, {
        title:   option.title,
        message: option.description
      }, { root: true });
    }
  }
};

provide('chatContext', context);

</script>
<template>
  <Loading v-if="isLoading" />
  <div class="error-content" v-else-if="!permissions?.list.canListSecrets">
    <div class="error-message" >
      You do not have permission to access Kopilot AI assistant service.
      Please contact your administrator or refer to our <a href="https://github.com/cnrancher/kopilot/tree/main/docs" target="_blank">documentation</a>
    </div>
  </div>
  <div v-else-if="errorAgentDeployment">
    <div class="error-message">
      {{ t(errorAgentDeployment.key) }}
    </div>
  </div>
  <div class="error-content" v-else-if="errorMessage">
    <div class="error-message">
      {{ errorMessage }}
      <br>
      Please ensure the Kopilot AI assistant services are correctly installed.
    </div>
  </div>

  <div v-else class="chat-container kopilot-ui">
    <div
      class="resize-bar"
      @mousedown.prevent.stop="resize"
      @touchstart.prevent.stop="resize"
    />
    <ChatView @close="close" />
  </div>
</template>
<style lang='scss' scoped>
.error-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  height: 100%;
  padding: 12px 12px;
}
.error-message {
  background: var(--error-banner-bg);
  color: var(--error-banner-text, var(--error));
  border: 1px solid var(--error);
  border-radius: 12px;
  box-shadow: 0 2px 8px 0 rgba(0, 0, 0, .04);
  padding: 12px;
  line-height: 21px;
}
.chat-container {
  height: calc(100vh - 55px);
  z-index: 20;
}

.resize-bar {
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  cursor: ew-resize;
  background: transparent;
  transition: background 0.2s;
  z-index: 20;
  opacity: 0;

  &:hover {
    background: var(--primary);
    opacity: 1;
  }
}
</style>
