import { createSharedComposable } from '@vueuse/core'
import {ref, computed, watch} from 'vue'
import { useStore } from 'vuex';
import { CONFIG_MAP } from '@shell/config/types';
import { AGENT_NAMESPACE, KOPILOT_AI_SCHEMA, TOOLS_CONFIG_RANCHER_NAME} from '../product';
import toolsConfigData from '../assets/rancher_ui_tools.json'

export function  useTools() {
  const store = useStore();
  const uiToolsNeedCreate = ref(false)
  const uiToolsSettings = ref({})
  const permissions = computed(() => {
    const canListConfigMaps = store.getters['management/canList'](CONFIG_MAP);
    const configMapschema = store.getters['management/schemaFor'](CONFIG_MAP);
    const canCreateConfigMaps = !!configMapschema?.resourceMethods?.find((verb) => 'PUT' === verb);
    return {
      list: {
        canListConfigMaps
      },
      create: {
        canCreateConfigMaps
      }
    }
  })
  const fetchUIToolsConfigSettings = async (errorMap, force = true) => {
    if (permissions.value?.list?.canListConfigMaps) {
      try {
        uiToolsSettings.value = await store.dispatch(`management/find`, {
          type: CONFIG_MAP,
          id:   `${ AGENT_NAMESPACE }/${ TOOLS_CONFIG_RANCHER_NAME }`,
          opt:  { watch: true, force }
        });
      uiToolsNeedCreate.value = false
      } catch (err) {
        if (err.status === 404) {
          uiToolsNeedCreate.value = true
        } else {
          errorMap.value.set(TOOLS_CONFIG_RANCHER_NAME, err);

        }
        console.warn(`Unable to fetch the ${ TOOLS_CONFIG_RANCHER_NAME } configMap: `, { err });
      }
    }
  }
  const saveToolsSettings = async (aiToolsRancherFormData, saveError) => {
    // ai tools config
    let configMapRancher;

    try {
      configMapRancher = await store.dispatch(`management/find`, {
        type: CONFIG_MAP,
        id:   `${ AGENT_NAMESPACE }/${ TOOLS_CONFIG_RANCHER_NAME }`,
      });
    } catch (err) {
      console.warn('Unable to fetch Kopilot UI Tools Rancher Config ConfigMap: ', { err });
      saveError.value.push(err);
    }
    
    if (configMapRancher) {
      configMapRancher.data = { config: JSON.stringify(aiToolsRancherFormData || {}) };

      try {
        await configMapRancher.save();
      } catch (err) {
        console.warn('Unable to save Kopilot UI Tools Rancher Config ConfigMap: ', { err });
        saveError.value.push(err);
      }
    } else {
      console.warn('Kopilot UI Tools Config Rancher ConfigMap not found, cannot save settings');
    }
  }
  async function createToolsDefinition() {
    const configMap = await store.dispatch('management/create', {
      type:     CONFIG_MAP,
      metadata: {
        name:        'kopilot-rancher-ui-tools',
        namespace:   AGENT_NAMESPACE,
        labels:      { app: 'kopilot-rancher-ui-tools' },
      },
      data: {
        config: JSON.stringify(toolsConfigData),
      }
    });

    try {
      await configMap.save();
    } catch (err) {
      console.warn(`Unable to create UI Tools Config ConfigMap ${ configMap.metadata.name }: `, { err });

      return {
        action:  'create',
        success: false,
        message: err
      };
    }
    await fetchUIToolsConfigSettings();
    return {
      action:  'create',
      success: true,
    };
  }
  
  return {
    uiToolsNeedCreate,
    uiToolsSettings,
    fetchUIToolsConfigSettings,
    saveToolsSettings,
    createToolsDefinition
  }
}

export const useSharedTools = createSharedComposable(useTools)