import { createSharedComposable } from '@vueuse/core'
import {ref, computed, watch} from 'vue'
import { useStore } from 'vuex';
import { SECRET, CONFIG_MAP } from '@shell/config/types';
import { AGENT_NAMESPACE, KOPILOT_AI_SCHEMA} from '../product';
import { base64Encode } from '@shell/utils/crypto';
export function  useAgents() {
  const store = useStore()
  const aiAgentConfigCRDs = ref([])
  const oauth2Secrets = ref([])
  const permissions = computed(() => {
      const canListSecrets = store.getters['management/canList'](SECRET);
      const canListAiAgentCRDS = canListSecrets && store.getters['management/canList'](KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG);
      const configMapschema = store.getters['management/schemaFor'](CONFIG_MAP);
      const canCreateConfigMaps = !!configMapschema?.resourceMethods?.find((verb) => 'PUT' === verb);
      const secretSchema = store.getters['management/schemaFor'](SECRET);
      const canCreateSecrets = !!secretSchema?.resourceMethods?.find((verb) => 'PUT' === verb);
      return {
        list: {
          canListSecrets,
          canListAiAgentCRDS
        },
        create: {
          canCreateConfigMaps,
          canCreateSecrets
        }
      }
  })
  const fetchAgentCRDS = async (errorMap) => {
    if (permissions.value?.list?.canListAiAgentCRDS) {
      try {
        const crds = await store.dispatch(`management/findAll`, {
          type: KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG,
          opt:  { watch: true }
        });
        const data = crds.filter((item) => item.metadata?.labels?.['kopilot.pandaria.io/rancher-ui'] === 'true')
        aiAgentConfigCRDs.value = data
        const oauth2SecretsPromises = data.filter((item) => item.spec.authenticationType === 'OAUTH2')
          .map((item) => store.dispatch(`management/find`, {
            type: SECRET,
            id:   `${ AGENT_NAMESPACE }/${ item.spec.authenticationSecret }`,
            opt:  { watch: true }
          }));
        const secrets = await Promise.all(oauth2SecretsPromises);
        oauth2Secrets.value = secrets
      } catch (err) {
        errorMap.value.set(KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG, err);
        console.warn(`Unable to fetch the ${ KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG } CRD: `, { err });
      }
    }
  }

  const saveAgentsSettings = async (aiAgentsFormData, saveError) => {
    // ai agents config
    let crds = [];
    let updatedSecrets = [];
    try {
      crds = await store.dispatch(`management/findAll`, {
        type: KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG,
        opt:  { watch: true }
      });

      crds = crds.filter((item) => item.metadata?.labels['kopilot.pandaria.io/rancher-ui'] === 'true')
    } catch (err) {
      console.warn('Unable to fetch Kopilot AI Agent Config CRDs: ', { err });
      saveError.value.push(err);
    }
    const { data: crdsToSave = [], newSecrets = {}, updateSecrets, removeSecrets, idKey} = aiAgentsFormData || {};

    for (const [k, v] of Object.entries(newSecrets)) {
      try {
        const aiAgentConfigCRD = crdsToSave.find((c) => c[idKey] === k);
        switch (aiAgentConfigCRD.spec.authenticationType) {
          case 'BASIC': {
            const password = base64Encode(v.password || '')
            const username = base64Encode(v.username || '')
            const d = {
              password,
              username
            }
            const secret = await store.dispatch('management/create', {
              type:     SECRET,
              metadata: {
                namespace:    AGENT_NAMESPACE,
                generateName: 'ai-agent-auth-',
                labels:       { 'app.kubernetes.io/managed-by': 'kopilot' }
              },
              data: d,
              _type: 'kubernetes.io/basic-auth'
            });

            secret._type = 'kubernetes.io/basic-auth';
            const savedSecret = await secret.save();
            // Update reference to the new secret in the corresponding AI Agent Config CRD
            aiAgentConfigCRD.spec.authenticationSecret = savedSecret.metadata.name;
          }
          break;
          case 'OAUTH2': {
            const d = {
              metadataEndpoint: base64Encode(v.data.metadataEndpoint || ''),
              clientID: base64Encode(v.data.clientID || ''),
              clientSecret: base64Encode(v.data.clientSecret || ''),
              scope: base64Encode(v.data.scope || ''),
            }
            if (d.metadataEndpoint && d.clientID && d.clientSecret) {
              const secret = await store.dispatch('management/create', {
                type:     SECRET,
                metadata: {
                  namespace:    AGENT_NAMESPACE,
                  generateName: 'ai-agent-auth-',
                  labels:       { 'app.kubernetes.io/managed-by': 'kopilot' }
                },
                data: d,
                _type: 'Opaque'
              });
              secret._type = 'Opaque';
              const savedSecret = await secret.save();
              // Update reference to the new secret in the corresponding AI Agent Config CRD
              aiAgentConfigCRD.spec.authenticationSecret = savedSecret.metadata.name;
              updatedSecrets.push(savedSecret)
            }
          }
          break;
        }
      } catch (err) {
        console.warn(`Unable to save secret: `, { err });
      }
    }

    try {
      const toUpdatedSecrets = []
      for (const [k, v] of Object.entries(updateSecrets)) {
        const crd = crdsToSave.find((item) => item[idKey] === k)
        switch (crd.spec.authenticationType) {
          case 'OAUTH2': {
            const d = {
              metadataEndpoint: base64Encode(v.data.metadataEndpoint || ''),
              clientID: base64Encode(v.data.clientID || ''),
              clientSecret: base64Encode(v.data.clientSecret || ''),
              scope: base64Encode(v.data.scope || ''),
            }
            toUpdatedSecrets.push({ id: crd.spec.authenticationSecret, data: d, agent: crd })
          }
        }
      }
      if (toUpdatedSecrets.length > 0) {
        const secretsResp = await Promise.allSettled(
          toUpdatedSecrets.map((item) => {
            return store.dispatch(`management/find`, {
              type: SECRET,
              id:   `${ AGENT_NAMESPACE }/${ item.id }`,
              opt:  { watch: true }
            })
          }),
        )
        secretsResp.forEach((item, index) => {
          if (item.status === 'rejected') {
            const s = toUpdatedSecrets[index]
            console.warn(`Secret ${s.id} for agent ${s.agent.spec.displayName} not found`)
          }
        })
        const secrets = secretsResp
          .filter((item) => item.status === 'fulfilled')
          .map((item) => item.value)
          .map((secret) => {
            secret.data = {
              ...(secret.data || {}),
              ...toUpdatedSecrets.find((s) => s.id === secret.metadata.name).data,
            };
            return secret
          })

        const updateSecretsPromises = secrets.map((item) => item.save())

        const updateSecretsResp = await Promise.allSettled(updateSecretsPromises)
        updateSecretsResp.forEach((item, index) => {
          if (item.status === 'rejected') {
            const s = secrets[index]
            const agent = toUpdatedSecrets.find((item) => item.id === s.id)
            console.warn(
              `Secret ${s.id} for agent ${agent.spec.displayName} update failed: ${item.reason}`,
            )
            return;
          }
          updatedSecrets.push(item.value)
        })
      }
    } catch (err) {
      console.warn('Update secret error: ',err)
    }

    for (const crd of crds) {
      const existsInForm = crdsToSave.find((c) => c.metadata.name === crd.metadata.name);

      if (!existsInForm) {
        // Remove existing CRD not present in the form anymore
        try {
          await crd.remove();
        } catch (err) {
          console.warn(`Unable to delete Kopilot AI Agent Config CRD ${ crd.metadata.name }: `, { err });
          saveError.value.push(err);
        }
      }
    }
    for (const crd of crdsToSave) {
      let aiAgentConfigCRD = crds.find((c) => c.metadata.name === crd.metadata.name);

      // Update existing CRD
      if (aiAgentConfigCRD) {
        // Preserve builtIn agents and only update enabled field
        if (aiAgentConfigCRD.spec.builtIn) {
          aiAgentConfigCRD.spec.enabled = crd.spec.enabled;
          aiAgentConfigCRD.spec.llmModelEnabled = crd.spec.llmModelEnabled;
          aiAgentConfigCRD.spec.llmModel = crd.spec.llmModel;
        } else {
          aiAgentConfigCRD.spec = crd.spec;
        }
      // Create new CRD
      } else {
        try {
          aiAgentConfigCRD = await store.dispatch('management/create', {
            type: KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG,
            ...crd,
          });
        } catch (err) {
          console.warn(`Create Kopilot AI Agent Config CRD ${ crd.metadata.name } error: `, { err });
          saveError.value.push(err);
        }
      }
      // Normalize authenticationSecret
      if (['OAUTH2', 'BASIC', 'HEADER'].includes(aiAgentConfigCRD.spec.authenticationType)) {
        aiAgentConfigCRD.spec.authenticationSecret = aiAgentConfigCRD.spec.authenticationSecret?.replaceAll(`${ AGENT_NAMESPACE }/`, '');
      } else {
        delete aiAgentConfigCRD.spec.authenticationSecret;
      }
      try {
        await aiAgentConfigCRD.save();
      } catch (err) {
        console.warn(`Unable to update Kopilot AI Agent Config CRD ${ crd.metadata.name }: `, { err });
        saveError.value.push(err);
      }
    }
    // remove secrets
    const toRemovedSecrets = []
    for (const [_, v] of Object.entries(removeSecrets)) {
      toRemovedSecrets.push({ id: v.id })
    }
    if (toRemovedSecrets.length > 0) {
      const removeSecretsResults = await Promise.allSettled(
        toRemovedSecrets.map((item) => {
          return store.dispatch(`management/find`, {
            type: SECRET,
            id:   `${ AGENT_NAMESPACE }/${ item.id }`,
            opt:  { watch: true }
          })
        })
      )
      removeSecretsResults.forEach((item, index) => {
        if (item.status === 'rejected') {
          const s = toRemovedSecrets[index]
          console.warn(`Secret ${s.id} not found or already deleted: `, item.reason);
          return;
        }
        const refCounts = crdsToSave.filter((crd) => crd.spec.authenticationType === 'OAUTH2' && crd.spec.authenticationSecret === item.value.metadata.name)
        if (refCounts >= 1) {
          return
        }
        item.value.remove();
      })
    }
    aiAgentConfigCRDs.value = [...crdsToSave];
    oauth2Secrets.value = updatedSecrets;
  }
  const mergeAiAgentConfigCRDsStatusUpdate = (updatedCrds) => {
    if (!updatedCrds || !aiAgentConfigCRDs.value) {
      return;
    }

    updatedCrds.forEach((storeCrd) => {
      const crd = aiAgentConfigCRDs.value?.find((c) => c.metadata.name === storeCrd.metadata.name);

      if (crd) {
        crd.status = storeCrd.status;
      }
    });
  }
  watch(
    () => store.getters['management/all'](KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG),
    mergeAiAgentConfigCRDsStatusUpdate,
    { deep: true }
  );
  return {
    aiAgentConfigCRDs,
    oauth2Secrets,
    fetchAgentCRDS,
    saveAgentsSettings
  }
}

export const useSharedAgents = createSharedComposable(useAgents)