import { useStore } from 'vuex';
import {  WORKLOAD_TYPES } from '@shell/config/types';
import { AGENT_NAMESPACE, AGENT_NAME } from '../product';
import {ref, computed, watch, onMounted} from 'vue'
const AIServiceState = {
  NotFound: 'not-found',
  Active: 'active',
  InProgress: 'in-progress',
  Updating: 'updating'
}
export function useAIService() {
  const store = useStore();
  const initiated = ref(false);
  const error = ref(null)
  const hasPermissions = computed(() => {
    const canListDeployments = !!store.getters['management/canList'](WORKLOAD_TYPES.DEPLOYMENT);
    // const canListConfigMaps = !!store.getters['management/canList'](CONFIG_MAP);

    // return canListDeployments && canListConfigMaps;
    return canListDeployments;
  });

  const aiAgentDeploymentState = computed(() => {
    if (!hasPermissions.value) {
      return undefined;
    }

    const deployments = store.getters['management/all'](WORKLOAD_TYPES.DEPLOYMENT);

    const deployment = deployments.find((d) => d.metadata?.name === AGENT_NAME && d.metadata?.namespace === AGENT_NAMESPACE);

    if (!initiated.value) {
      return undefined;
    }

    if (!deployment) {
      return AIServiceState.NotFound;
    }

    return deployment?.state;
  });
  async function fetchDeployments() {
    if (!hasPermissions.value) {
      return;
    }

    try {
      await store.dispatch('management/findAll', { type: WORKLOAD_TYPES.DEPLOYMENT });
    } catch (err) {
      // Guard against the resource cache being torn down while the AI service is being
      // (re)installed, so a transient rejection doesn't become an unhandled promise rejection.
      console.warn('Failed to fetch AI agent deployments:', err);
    }
  }
  if(!localStorage.getItem('__kopilot-dev__')) {
    watch(() => aiAgentDeploymentState.value, (newState) => {
      if (newState === AIServiceState.NotFound) {
        error.value = { key: 'kopilot.error.services.deployment.notFound' };
      } else {
        error.value = null;
      }
    });
  }
  

  onMounted(async() => {
    await fetchDeployments();

    initiated.value = true;
  });
  return {
    hasPermissions,
    aiAgentDeploymentState,
    error,
  };
}