import { createSharedComposable } from '@vueuse/core'
import {ref, computed} from 'vue'
import { useStore } from 'vuex';
import { SECRET, CONFIG_MAP } from '@shell/config/types';
import { AGENT_NAMESPACE, AGENT_CONFIG_CONFIG_MAP_NAME, AGENT_CONFIG_SECRET_NAME, AGENT_CONFIG_LLM_SECRET_NAME, } from '../product';
import { base64Decode, base64Encode } from '@shell/utils/crypto';
export function useModels() {
  const llmSecretKeys = ['ACTIVE_LLM', 'LLM_PROVIDER', 'LLM_BASE_URL', 'LLM_API_KEY', 'LLM_MODEL', 'LLM_TEMPERATURE', 'SECURITY_MODE', 'LLM_AWS_REGION' ];
  // const secretKeys = ['LANGFUSE_PUBLIC_KEY', 'LANGFUSE_SECRET_KEY'];
  // const configMapKeys = ['LANGFUSE_ENABLE', 'LANGFUSE_BASE_URL']
  const store = useStore();
  const llmSecret = ref(null);
  const secret = ref(null);
  const configMap = ref(null);

  const permissions = computed(() => {
    const canListConfigMaps = store.getters['management/canList'](CONFIG_MAP);
    const canListSecrets = store.getters['management/canList'](SECRET);
    const configMapschema = store.getters['management/schemaFor'](CONFIG_MAP);
    const canCreateConfigMaps = !!configMapschema?.resourceMethods?.find((verb) => 'PUT' === verb);
    const secretSchema = store.getters['management/schemaFor'](SECRET);
    const canCreateSecrets = !!secretSchema?.resourceMethods?.find((verb) => 'PUT' === verb);
      return {
        list: {
          canListConfigMaps,
          canListSecrets,
        },
        create: {
          canCreateConfigMaps,
          canCreateSecrets
        }
      }
  })
  const modelSettings = computed(() => {
    const settingsFormData = {};
    const llmData = llmSecret.value?.data ?? {};
    // const secretData = secret.value?.data;
    // const configMapData = configMap.value?.data;
    [...Object.entries(llmData)].forEach(([k,v]) => {
      settingsFormData[k] = base64Decode(v ?? '');
    })
    // if (llmData /* && secretData && configMapData */) {
    //   for (const entry in llmData) {
    //     settingsFormData[entry] = base64Decode(llmData[entry] ?? '');
    //   }
    //   // for (const entry in secretData) {
    //   //   settingsFormData[entry] = base64Decode(secretData[entry] ?? '');
    //   // }
    //   // const env = configMapData.env ?? '';
    //   // configMapKeys.forEach((k) => {
    //   //   const reg = new RegExp(`^(${k})="(.+)"`, 'm')
    //   //   const m = env.match(reg);
    //   //   if (m && m.length === 3) {
    //   //     settingsFormData[k]=m[2];
    //   //   }
    //   // })
    // }
    return settingsFormData;
  });
  const fetchLLMConfig = async (errorMap) => {
    if (permissions.value?.list?.canListSecrets) {
      try {
        llmSecret.value = await store.dispatch(`management/find`, {
          type: SECRET,
          id:   `${ AGENT_NAMESPACE }/${ AGENT_CONFIG_LLM_SECRET_NAME }`,
          opt:  { watch: true }
        });
      } catch (err) {
        errorMap.value.set(AGENT_CONFIG_LLM_SECRET_NAME, err);
        console.warn(`Unable to fetch the ${ AGENT_CONFIG_LLM_SECRET_NAME } secret: `, { err });
      }
    }
  }
  // const fetchAgentConfig = async () => {
  //   if (permissions.value?.list?.canListSecrets) {
  //     try {
  //       secret.value = await store.dispatch(`management/find`, {
  //         type: SECRET,
  //         id:   `${ AGENT_NAMESPACE }/${ AGENT_CONFIG_SECRET_NAME }`,
  //         opt:  { watch: true }
  //       });
  //     } catch (err) {
  //       errorMap.value.set(AGENT_CONFIG_SECRET_NAME, err);
  //       console.warn(`Unable to fetch the ${ AGENT_CONFIG_SECRET_NAME } secret: `, { err });
  //     }
  //   }
  // }
  // const fetchAgentConfigMap = async (errorMap) => {
  //   if (permissions.value?.list?.canListConfigMaps) {
  //     try {
  //       configMap.value = await store.dispatch(`management/find`, {
  //         type: CONFIG_MAP,
  //         id:   `${ AGENT_NAMESPACE }/${ AGENT_CONFIG_CONFIG_MAP_NAME }`,
  //         opt:  { watch: true }
  //       });
  //     } catch (err) {
  //       errorMap.value.set(AGENT_CONFIG_CONFIG_MAP_NAME, err);
  //       console.warn(`Unable to fetch the ${ AGENT_CONFIG_CONFIG_MAP_NAME } configMap: `, { err });
  //     }
  //   }
  // }
  const fetchModelSetings = async (errorMap) => {
    await Promise.all([fetchLLMConfig(errorMap), /*fetchAgentConfig(errorMap), fetchAgentConfigMap(errorMap)*/])
  }

  const saveModelSettings = async (formData, saveError) => {
    const copyAndEncodeData = (t, c) => {
      t[c] = base64Encode(formData[c] ?? '');
      return t;
    }
    // llm config
    const llmSecretDataToSave = [...Object.keys(formData)].filter((k) => llmSecretKeys.includes(k)).reduce(copyAndEncodeData, {});
    // const llmSecretDataToSave = llmSecretKeys.reduce(copyAndEncodeData, {});
    // const secretDataToSave = secretKeys.reduce(copyAndEncodeData, {});
    // const configMapDataToSave = configMap.value.data.env ? configMapKeys.reduce((t, c) => {
    //   const reg = new RegExp(`^${c}="(.+)"`, 'm');
    //   t.env = t.env.replace(reg, `${c}="${formData[c]}"`);
    //   return t;
    // }, {env: configMap.value.data.env}) : configMapKeys.reduce((t,c) => {
    //   t.env = `${t.env}${c}="${formData[c]}"\n`;
    //   return t;
    // }, {env: ''});
    Object.assign(llmSecret.value.data, llmSecretDataToSave);
    // Object.assign(secret.value.data, secretDataToSave);
    // Object.assign(configMap.value.data, configMapDataToSave);
    try {
      await Promise.all([llmSecret.value.save(),/* secret.value.save(), configMap.value.save() */])
    } catch (err) {
      saveError.value.push(err);
    }
  }

  return {
    llmSecret,
    modelSettings,
    permissions,
    fetchModelSetings,
    saveModelSettings,
    fetchLLMConfig,
  }
}

export const useSharedModels = createSharedComposable(useModels)
